/** Loose structural view of a parsed script JSON for the shared rules. */
function toRulesScript(raw: unknown): (RulesScript & { characterRows: { name: string; identity: string }[]; stage?: string; storyboardGroups?: RulesScript["groups"]; synopsis?: string; pendingItems?: string[]; tempCharacterStates?: Record<string, TempCharacterState> }) | null {
if (raw == null || typeof raw !== "object" || Array.isArray(raw)) return null;
const r = raw as Record<string, unknown>;
const groups = Array.isArray(r.groups) ? (r.groups as RulesScript["groups"]) : [];
const characterRows = Array.isArray(r.characterRows)
? (r.characterRows as { name?: unknown; identity?: unknown }[]).map((row) => ({
name: typeof row?.name === "string" ? row.name : "",
identity: typeof row?.identity === "string" ? row.identity : "",
}))
: [];
return {
groups,
speechRate: typeof r.speechRate === "number" && r.speechRate > 0 ? r.speechRate : 5,
targetSeconds: typeof r.targetSeconds === "number" ? r.targetSeconds : 0,
storyboardConfig:
r.storyboardConfig != null && typeof r.storyboardConfig === "object"
? (r.storyboardConfig as RulesScript["storyboardConfig"])
: undefined,
characterRows,
stage: typeof r.stage === "string" ? r.stage : undefined,
storyboardGroups: Array.isArray(r.storyboardGroups)
? (r.storyboardGroups as RulesScript["groups"])
: undefined,
synopsis: typeof r.synopsis === "string" ? r.synopsis : undefined,
pendingItems: Array.isArray(r.pendingItems)
? r.pendingItems.filter((x): x is string => typeof x === "string")
: undefined,
tempCharacterStates:
r.tempCharacterStates != null && typeof r.tempCharacterStates === "object" && !Array.isArray(r.tempCharacterStates)
? (r.tempCharacterStates as Record<string, TempCharacterState>)
: undefined,
};
}

async function loadSpeakerRegistry(
ctx: Ctx,
projectId: number,
script: { characterRows: { name: string; identity: string }[] },
): Promise<{
registry: { name: string; aliases: string[] }[];
registeredNames: string[];
}> {
const db = ctx.db<typeof schema>();
const chars = await db
.select()
.from(schema.characters)
.where(eq(schema.characters.projectId, projectId));
return {
registry: [
...script.characterRows.map((r) => ({ name: r.name, aliases: [r.identity] })),
...chars.map((c) => ({ name: c.name, aliases: [c.role] })),
],
registeredNames: chars.map((c) => c.name),
};
}

async function validateProjectScript(
ctx: Ctx,
projectId: number,
script: NonNullable<ReturnType<typeof toRulesScript>>,
): Promise<ValidationOut> {
const { registry, registeredNames } = await loadSpeakerRegistry(ctx, projectId, script);
// 大纲是临时人物检出的文字来源之一（大纲点名要出场的人）。
const db = ctx.db<typeof schema>();
const projRows = await db
.select()
.from(schema.projects)
.where(eq(schema.projects.id, projectId))
.limit(1);
// v4.79：AI解剖套用项目（source = "ai-dissect"）分镜确认跳过严格
// 审核拦截——validateScriptData 收到 skipStrictBlockers 后，严格硬
// 问题只检出展示、不进 blockers；其余拦截口径不变。
return validateScriptData(script, registry, registeredNames, projRows[0]?.outline ?? "", {
skipStrictBlockers: (projRows[0]?.source ?? "") === "ai-dissect",
});
}

/** v4.79：项目是否为 AI解剖一键套用生成（分镜确认跳过严格审核）。 */
async function isAiDissectProject(ctx: Ctx, projectId: number): Promise<boolean> {
const db = ctx.db<typeof schema>();
const rows = await db
.select({ source: schema.projects.source })
.from(schema.projects)
.where(eq(schema.projects.id, projectId))
.limit(1);
return (rows[0]?.source ?? "") === "ai-dissect";
}

