// v5.16：附图人物 id / 托管链接哈希在库里存 JSON 数组文本；历史行
// 是空串、坏值一律回落空数组，绝不让一条旧记录拖垮整个列表。
function parseCoverRefIdList(raw: string | null | undefined): number[] {
  if (!raw) return [];
  try {
    const v: unknown = JSON.parse(raw);
    if (!Array.isArray(v)) return [];
    return v.filter(
      (x): x is number => typeof x === "number" && Number.isFinite(x),
    );
  } catch {
    return [];
  }
}

function parseCoverRefHashList(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const v: unknown = JSON.parse(raw);
    if (!Array.isArray(v)) return [];
    return v.filter((x): x is string => typeof x === "string");
  } catch {
    return [];
  }
}

async function toCoverRecordOut(
  ctx: Ctx,
  row: CoverRecordRow,
): Promise<z.infer<typeof coverRecordOut>> {
  return {
    id: row.id,
    projectId: row.projectId,
    projectName: row.projectName,
    title: row.title,
    styleId: row.styleId,
    styleName: row.styleName,
    ratio: row.ratio,
    layoutType: row.layoutType,
    promptZh: row.promptZh,
    promptEn: row.promptEn,
    analysisJson: row.analysisJson,
    model: row.model,
    quality: row.quality,
    taskId: row.taskId ?? null,
    line: row.line,
    status: row.status,
    refCount: row.refCount ?? null,
    refCharIds: parseCoverRefIdList(row.refCharIds),
    refHostHashes: parseCoverRefHashList(row.refHostHashes),
    degradeReason: row.degradeReason ?? null,
    refFetch: parseCoverRefFetch(row.refFetchJson),
    stagedKey: row.stagedKey ?? null,
    imageUrl: row.stagedKey ? await blobUrlOrNull(ctx, row.stagedKey) : null,
    previewUrl: await previewUrlForKey(ctx, row.stagedKey ?? null),
    mimeType: row.mimeType ?? null,
    error: row.error ?? null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

