async function toAssetPresetOut(
ctx: Ctx,
row: AssetPresetRow,
imageRows?: AssetPresetImageRow[],
): Promise<z.infer<typeof assetPresetOut>> {
const db = ctx.db<typeof schema>();
let imgs =
imageRows ??
(await db
.select()
.from(schema.assetPresetImages)
.where(eq(schema.assetPresetImages.presetId, row.id))
.orderBy(
asc(schema.assetPresetImages.sortOrder),
asc(schema.assetPresetImages.id),
));
// v5.56 主体图造型回填（沿用口径）：主体图（第一张）还没有自己
// 的造型时，卡片现有造型就是它的造型——读取时把备注「造型：」
// 段（「外貌：」旧段次之）落盘进主体图的 look 列，保证之后切
// 换主体、再切回来时这张图的造型能原样恢复、不被新主体造型
// 顶掉。写失败不挡读取（下次读会再回填）。
const primaryImg = imgs[0];
if (primaryImg && !primaryImg.look.trim()) {
  const segLook = noteSegmentValue(row.cardNote, ["造型", "外貌"]);
  if (segLook) {
    try {
      await db
        .update(schema.assetPresetImages)
        .set({ look: segLook })
        .where(eq(schema.assetPresetImages.id, primaryImg.id));
      imgs = imgs.map((im, i) => (i === 0 ? { ...im, look: segLook } : im));
    } catch {
      /* 回填失败不挡读取 */
    }
  }
}
return {
id: row.id,
name: row.name,
locked: row.locked === 1,
personZh: row.personZh,
personEn: row.personEn,
hairZh: row.hairZh,
hairEn: row.hairEn,
hatZh: row.hatZh,
hatEn: row.hatEn,
faceZh: row.faceZh,
faceEn: row.faceEn,
neckZh: row.neckZh,
neckEn: row.neckEn,
topZh: row.topZh,
topEn: row.topEn,
armsZh: row.armsZh,
armsEn: row.armsEn,
bottomZh: row.bottomZh,
bottomEn: row.bottomEn,
shoesZh: row.shoesZh,
shoesEn: row.shoesEn,
extraZh: row.extraZh,
extraEn: row.extraEn,
cardRole: row.cardRole,
cardNote: row.cardNote,
category: row.category,
gender: row.gender,
ageGroup: row.ageGroup,
classUncertain: row.classUncertain === 1,
classNote: row.classNote,
pendingLook: row.pendingLook,
pendingVoice: row.pendingVoice,
pendingTone: row.pendingTone,
pendingSource: row.pendingSource,
pendingJobId: row.pendingJobId,
pendingUpdatedAt: row.pendingUpdatedAt,
pendingRollback: row.pendingRollback,
fromCard: row.fromCard === 1,
images: await Promise.all(
imgs.map(async (im, idx) => ({
id: im.id,
url: await ctx.blobs.getUrl(im.imageBlobKey),
previewUrl: await previewUrlForKey(ctx, im.imageBlobKey),
fileName: im.fileName,
look: im.look,
pendingLook: im.pendingLook,
pendingJobId: im.pendingJobId,
pendingUpdatedAt: im.pendingUpdatedAt,
pendingRollback: im.pendingRollback,
isPrimary: idx === 0,
})),
),
updatedAt: row.updatedAt.toISOString(),
};
}

/** All image rows of one preset, 主图 (lowest sortOrder) first. */
async function loadPresetImages(ctx: Ctx, presetId: number) {
const db = ctx.db<typeof schema>();
return db
.select()
.from(schema.assetPresetImages)
.where(eq(schema.assetPresetImages.presetId, presetId))
.orderBy(
asc(schema.assetPresetImages.sortOrder),
asc(schema.assetPresetImages.id),
);
}

/**
 * v5.56：把卡片当前主体图（第一张）的 look 列同步为给定造型。
 * 卡片造型段与主体图造型是同一份值的两处存法：凡是经「卡片
 * 造型」口径改动造型的动作（普通保存、卡级待确认转正 / 恢复）
 * 都在写完 cardNote 后调它，保证切主体前后两处不脱节。没有图
 * 的卡直接跳过。写失败不抛（调用方的主写已经落库，下次读取
 * 主体图回填会再对齐）。
 */
async function syncPrimaryImageLook(
  ctx: Ctx,
  presetId: number,
  lookValue: string,
): Promise<void> {
  try {
    const imgs = await loadPresetImages(ctx, presetId);
    const primary = imgs[0];
    if (!primary || primary.look === lookValue) return;
    const db = ctx.db<typeof schema>();
    await db
      .update(schema.assetPresetImages)
      .set({ look: lookValue })
      .where(eq(schema.assetPresetImages.id, primary.id));
  } catch {
    /* 同步失败不挡主写 */
  }
}

/** 解析 asset_preset_images.pending_rollback（{"look": "..."}；
 * 空串 / 坏值 = 无留底，回 null）。 */
function parseImagePendingRollback(
  raw: string,
): { look: string } | null {
  if (!raw) return null;
  try {
    const v = JSON.parse(raw) as { look?: unknown };
    return typeof v.look === "string" ? { look: v.look } : null;
  } catch {
    return null;
  }
}

/**
 * v3.66：目标卡上是否已有一张与指定原图「字节完全相同」的复制图。
 * blob 的 etag 就是内容标识：etag 相同即同一份字节。同一 key 的行
 * 是共享引用本身、不算复制（调用方会先清掉引用行再判断）。
 */
async function presetHasIdenticalImageCopy(
ctx: Ctx,
presetId: number,
sourceKey: string,
): Promise<boolean> {
const srcHead = await ctx.blobs.head(sourceKey);
if (!srcHead) return false;
const imgs = await loadPresetImages(ctx, presetId);
for (const im of imgs) {
if (im.imageBlobKey === sourceKey) continue;
const h = await ctx.blobs.head(im.imageBlobKey);
if (h && h.etag === srcHead.etag) return true;
}
return false;
}

/**
 * A blob key can be shared between a script character card and a
 * library card image (the blob API has no byte-copy), so a blob is
 * only deleted once NOTHING references it any more.
 */
async function blobUsedByCharacter(ctx: Ctx, key: string): Promise<boolean> {
const db = ctx.db<typeof schema>();
const rows = await db
.select({ id: schema.characters.id })
.from(schema.characters)
.where(eq(schema.characters.imageBlobKey, key))
.limit(1);
return rows.length > 0;
}

async function blobUsedByLibrary(ctx: Ctx, key: string): Promise<boolean> {
const db = ctx.db<typeof schema>();
const rows = await db
.select({ id: schema.assetPresetImages.id })
.from(schema.assetPresetImages)
.where(eq(schema.assetPresetImages.imageBlobKey, key))
.limit(1);
return rows.length > 0;
}

async function blobUsedBySceneAsset(ctx: Ctx, key: string): Promise<boolean> {
const db = ctx.db<typeof schema>();
const rows = await db
.select({ id: schema.sceneAssetCards.id })
.from(schema.sceneAssetCards)
.where(eq(schema.sceneAssetCards.imageBlobKey, key))
.limit(1);
return rows.length > 0;
}

async function deleteBlobIfUnreferenced(ctx: Ctx, key: string) {
if (await blobUsedByCharacter(ctx, key)) return;
if (await blobUsedByLibrary(ctx, key)) return;
if (await blobUsedBySceneAsset(ctx, key)) return;
await ctx.blobs.delete(key);
// v3.64：原图删掉时，它的预览图一并删，不留孤儿预览。
const tk = thumbKeyFor(key);
if (await ctx.blobs.head(tk)) await ctx.blobs.delete(tk);
}

/** 备注 for a sent preset: the ten Chinese part descriptions, labelled. */
function presetNoteZh(p: AssetPresetRow): string {
const parts: [string, string][] = [
["人物", p.personZh],
["发型", p.hairZh],
["帽子", p.hatZh],
["面部", p.faceZh],
["脖子", p.neckZh],
["上衣", p.topZh],
["手臂", p.armsZh],
["下装", p.bottomZh],
["鞋子", p.shoesZh],
["补充", p.extraZh],
];
return parts
.filter(([, v]) => v.trim())
.map(([label, v]) => `${label}：${v.trim()}`)
.join("；");
}

