async function ensureAssetPresetsSeeded(ctx: Ctx) {
const db = ctx.db<typeof schema>();
const rows = await db.select().from(schema.assetPresets).limit(1);
if (rows.length > 0) return;
const flag = await db
.select()
.from(schema.assetMeta)
.where(eq(schema.assetMeta.key, "starter_seeded"));
if (flag.length > 0) return;
for (const p of STARTER_PRESETS) {
await db.insert(schema.assetPresets).values(p);
}
await db
.insert(schema.assetMeta)
.values({ key: "starter_seeded", value: "1"});
}


const DEFAULT_CATEGORIES = ["主角", "配角", "群演", "未分类"];

/**
 * Library categories (v3.26): seed the four default buckets once, run
 * the one-time unlock (the library no longer locks cards — every card
 * is editable/deletable by default) and the one-time default filing
 * of the rebuilt 测1 cards. Both one-time steps are guarded by
 * asset_meta flags so later user changes are never overwritten.
 */
async function ensureLibraryCategories(ctx: Ctx) {
const db = ctx.db<typeof schema>();
const cats = await db.select().from(schema.assetCategories);
if (cats.length === 0) {
for (let i = 0; i < DEFAULT_CATEGORIES.length; i++) {
await db.insert(schema.assetCategories).values({ name: DEFAULT_CATEGORIES[i]!, sortOrder: i });
}
}
const flags = await db.select().from(schema.assetMeta);
const has = (k: string) => flags.some((f) => f.key === k);
if (!has("library_unlock_all_v1")) {
await db.update(schema.assetPresets).set({ locked: 0 });
await db.insert(schema.assetMeta).values({ key: "library_unlock_all_v1", value: "1" });
}
if (!has("library_category_defaults_v1")) {
const defaults: Record<string, string> = {
"林哥": "主角",
"小帅": "主角",
"小美": "主角",
"小帅爸爸": "配角",
"林哥小弟": "群演",
};
const rows = await db.select().from(schema.assetPresets);
for (const r of rows) {
const cat = defaults[r.name.trim()];
if (cat && (r.category === "" || r.category === "未分类")) {
await db.update(schema.assetPresets).set({ category: cat }).where(eq(schema.assetPresets.id, r.id));
}
}
await db.insert(schema.assetMeta).values({ key: "library_category_defaults_v1", value: "1" });
}
// One-time restore (v3.27): the two starter cards （默认预设·金龙帽虎头T、
// 粉色双马尾酷甜少女） were lost from the durable library before v3.26 —
// the table was no longer empty, so the original seeding never re-ran,
// and v3.26 shipped with only the 5 rebuilt 测1 cards while its log
// wrongly claimed 7. Restore any starter that is missing BY NAME from
// the original STARTER_PRESETS definitions, unlocked (the library no
// longer locks cards; 粉色双马尾 included). Guarded by its own flag:
// if the user later deletes a restored card on purpose, it stays
// deleted and is never resurrected.
if (!has("library_restore_starters_v1")) {
const rows = await db.select().from(schema.assetPresets);
const names = new Set(rows.map((r) => r.name.trim()));
for (const p of STARTER_PRESETS) {
const starterName = p.name?.trim() ?? "";
if (starterName && !names.has(starterName)) {
await db.insert(schema.assetPresets).values({ ...p, locked: 0 });
}
}
await db.insert(schema.assetMeta).values({ key: "library_restore_starters_v1", value: "1" });
}
}

async function loadCategoryCounts(ctx: Ctx): Promise<{ name: string; count: number }[]> {
const db = ctx.db<typeof schema>();
const cats = await db.select().from(schema.assetCategories).orderBy(asc(schema.assetCategories.sortOrder), asc(schema.assetCategories.id));
const rows = await db.select({ category: schema.assetPresets.category }).from(schema.assetPresets);
const counts = new Map<string, number>();
for (const r of rows) counts.set(r.category, (counts.get(r.category) ?? 0) + 1);
const out = cats.map((c) => ({ name: c.name, count: counts.get(c.name) ?? 0 }));
// Any category value still on a card but missing a row (legacy data)
// is surfaced too, so counts always add up.
for (const [name, count] of counts) {
if (name && !out.some((o) => o.name === name)) out.push({ name, count });
}
return out;
}

