type GenContextResult =
| { ok: false; error: string }
| {
ok: true;
detail: ProjectDetail;
styleLabel: string;
castLines: string;
/** v4.16：项目还没有已命名人物卡（人物资产改为确认分镜后才建）。 */
noCast: boolean;
};

async function loadGenContext(
ctx: Ctx,
projectId: number,
): Promise<GenContextResult> {
const detail = await loadProjectDetail(ctx, projectId);
if (!detail) return { ok: false, error: "项目不存在" };
// v4.16：没有人物卡不再拦截剧本生成（承接 v3.54 大纲口径）。人物
// 资产按新流程在确认分镜之后才建：零人物时剧本按大纲里的「故事
// 角色位」称呼写（与大纲同一口径），不假装已有资产人物出演、也不
// 给人物起大纲之外的具体姓名；等分镜确认后，再在分镜页点「按分
// 镜写资产提示词」按分镜归并建卡。
const named = detail.characters.filter((c) => c.name.trim());
const noCast = named.length === 0;
if (!detail.outline.trim()) {
return { ok: false, error: "故事大纲还是空的" };
}
const styleLabel =
detail.stylePreset === "自定义"
? detail.styleCustom.trim() || "自定义风格"
: detail.stylePreset;
const castLines = noCast
? "（本项目还没有人物卡：按故事大纲里的「故事角色位」称呼人物——大纲里怎么称呼就怎么用，如 现在小孩、以前小孩、妈妈、店长；不要给人物起大纲之外的具体姓名，不要假装某位已有资产人物出演；路人/群演只一笔带过、不给台词）"
: detail.characters
.map((c, i) => {
const nm = c.name.trim() || `未命名人物${i + 1}`;
// Single-name口径 (v3.41): 身份 now lives in the note as an
// “身份：…” segment (the role column is retired); surface it
// explicitly so generation still sees it.
const role = c.role.trim() || extractIdentityFromNote(c.note);
const note = c.note.trim() || "（无备注）";
return role
? `- ${nm}｜扮演/身份：${role}｜性格/外貌备注：${note}`
: `- ${nm}｜性格/外貌备注：${note}`;
})
.join("\n");
// v4.03：场景设置已删除——生成提示词不再注入任何场景字段，
// 场景全靠大纲 / 剧本提示词本身写入（每段场景名仍由规划与正文给出）。
return { ok: true, detail, styleLabel, castLines, noCast };
}

function genErrorMessage(e: unknown): string {
if (InferenceSchemaError.is(e)) return "生成结果结构不完整，请再试一次";
return `生成失败：${e instanceof Error ? e.message : String(e)}`;
}

/**
 * v4.74 子批错误分类（v4.86 起由融合层 / 输出层 / 纯文本规划共用）：
 * 四类判定回结构化 errorKind 给客户端熔断判定用，文案不带
 * 「已自动重试」口径——子批动作一律单次推理、不在服务端重试，重试与
 * 熔断（慢输出自动拆小、总预算上限）全由客户端编排，避免多层重试叠加
 * 烧配额（v4.73 实测最坏 6 次客户端尝试 × 服务端 2 次 = 12 次推理）。
 *   - timeout：本次尝试耗时接近推理超时上限，或原文带超时词——客户端
 *     判「慢输出」型失败：不重试同一大批，自动拆成更小的批接着跑；
 *   - overload：图片超量类；refusal：模型拒识；schema：结构不完整；
 *   - other：保留原始报错。
 */
const dissectUnitErrorKind = z.enum(["timeout", "overload", "refusal", "schema", "other"]);
type DissectUnitErrorKind = z.infer<typeof dissectUnitErrorKind>;

function dissectUnitFailure(
  e: unknown,
  frameCount: number,
  elapsedMs: number,
  timeoutSecs: number,
): { kind: DissectUnitErrorKind; message: string } {
  if (InferenceSchemaError.is(e)) {
    return { kind: "schema", message: "生成结果结构不完整，请再试一次" };
  }
  const raw = e instanceof Error ? e.message : String(e);
  if (elapsedMs >= (timeoutSecs - 15) * 1000 || /timed?\s?out|timeout|超时/i.test(raw)) {
    return {
      kind: "timeout",
      message: "AI 这一批生成太慢、超时了（输出太大、生成太久，网关先把连接掐了）",
    };
  }
  if (
    /too many images|image.{0,20}(limit|exceed|too many)|payload|413|too large|request entity/i.test(raw) ||
    (/inference failed/i.test(raw) && frameCount >= 6)
  ) {
    return {
      kind: "overload",
      message: `图片太多，AI 一次吃不下：这一批发了 ${frameCount} 帧，推理直接失败了`,
    };
  }
  if (/refus|content policy|safety|moderation|not allowed|policy violation/i.test(raw)) {
    return { kind: "refusal", message: "AI 拒绝识别这段画面（触发了内容限制）" };
  }
  return { kind: "other", message: `生成失败：${raw}` };
}

/** 子批动作共用的基础信息上下文行（标题/达人/时长/描述 + 用户拆解笔记）。 */
function dissectCtxLines(args: {
  title?: string;
  creatorName?: string;
  durationText?: string;
  description?: string;
  hook?: string;
  structure?: string;
  rhythm?: string;
  humor?: string;
  emotion?: string;
}): string[] {
  const lines: string[] = [];
  if (args.title?.trim()) lines.push(`标题：${args.title.trim()}`);
  if (args.creatorName?.trim()) lines.push(`达人：${args.creatorName.trim()}`);
  if (args.durationText?.trim()) lines.push(`时长：${args.durationText.trim()}`);
  if (args.description?.trim()) lines.push(`视频描述：${args.description.trim().slice(0, 1500)}`);
  const notes: string[] = [];
  if (args.hook?.trim()) notes.push(`前3秒钩子：${args.hook.trim().slice(0, 800)}`);
  if (args.structure?.trim()) notes.push(`结构：${args.structure.trim().slice(0, 800)}`);
  if (args.rhythm?.trim()) notes.push(`节奏：${args.rhythm.trim().slice(0, 800)}`);
  if (args.humor?.trim()) notes.push(`幽默机制：${args.humor.trim().slice(0, 800)}`);
  if (args.emotion?.trim()) notes.push(`情绪曲线：${args.emotion.trim().slice(0, 800)}`);
  if (notes.length > 0) {
    lines.push(
      "",
      "用户在「爆款拆解」里已填的内容（辅助上下文，与画面冲突时以画面为准）：",
      ...notes,
    );
  }
  return lines;
}

