/** Clean a value for one labelled note segment （段内不留 ；; 换行，
 * 免得备注提取造型 / 音色 / 语气基调时被截断）。 */
function cleanSegmentValue(v: string): string {
  return v
    .trim()
    .replace(/[；;\n]+/g, "，")
    .replace(/。+$/, "")
    .trim();
}

/** Read one “标签：值” segment value from a note (first matching
 * label wins; 与客户端 charbench labelledSegment 同口径）。 */
function noteSegmentValue(note: string, labels: string[]): string {
  for (const label of labels) {
    const m = note.match(new RegExp(`${label}[:：]\\s*([^；;\\n]+)`));
    if (m?.[1]) return m[1].trim().replace(/。+$/, "").trim();
  }
  return "";
}

/** Strip every segment carrying one of the given labels from a
 * note, cleaning up dangling separators （与客户端 charbench
 * stripLabelledSegments 同口径）。 */
function stripNoteSegments(note: string, labels: string[]): string {
  let out = note;
  for (const label of labels) {
    out = out.replace(new RegExp(`${label}[:：]\\s*[^；;\\n]+`, "g"), "");
  }
  return out
    .replace(/[；;]\s*[；;]+/g, "；")
    .replace(/^[；;，,、\s]+/, "")
    .replace(/[；;，,、\s]+$/, "")
    .trim();
}

/** Set one labelled segment to a value — or remove the segment
 * entirely when the value is empty. All segments carrying any of
 * `stripLabels` are removed first (so the legacy 「外貌：」 alias
 * is folded into 「造型：」), then the new segment is appended
 * under `writeLabel`. Every other part of the note stays verbatim.
 * v5.53 confirmPresetPending uses this to write confirmed pending
 * values into cardNote through the same segment convention the
 * detail modal saves with. */
function setNoteSegmentValue(
  note: string,
  stripLabels: string[],
  writeLabel: string,
  rawValue: string,
): string {
  const base = stripNoteSegments(note, stripLabels);
  const value = cleanSegmentValue(rawValue);
  if (!value) return base;
  const seg = `${writeLabel}：${value}`;
  return base ? `${base}；${seg}` : seg;
}

/** Insert or replace one “标签：值” segment in a note, keeping every
 * other part of the note （造型、身份、自由文本） verbatim. */
function upsertNoteSegment(note: string, label: string, rawValue: string): string {
  const value = cleanSegmentValue(rawValue);
  if (!value) return note;
  const re = new RegExp(`${label}[:：]\\s*[^；;\\n]+`);
  if (re.test(note)) return note.replace(re, `${label}：${value}`);
  const base = note.trim();
  if (!base) return `${label}：${value}`;
  const sep = /[；;。]$/.test(base) ? "" : "；";
  return `${base}${sep}${label}：${value}`;
}

