function parseWeights(raw: string): z.infer<typeof geneWeights> {
  try {
    const v = JSON.parse(raw) as Record<string, unknown>;
    const out = { ...DEFAULT_WEIGHTS };
    for (const k of Object.keys(DEFAULT_WEIGHTS) as (keyof typeof DEFAULT_WEIGHTS)[]) {
      const n = Number(v[k]); if (Number.isFinite(n)) out[k] = Math.max(0, Math.min(200, Math.round(n)));
    }
    return out;
  } catch { return { ...DEFAULT_WEIGHTS }; }
}
function parseFrames(raw: string): z.infer<typeof frameInfo>[] {
  try { const v = JSON.parse(raw) as unknown; if (!Array.isArray(v)) return []; return v.filter((x): x is z.infer<typeof frameInfo> => typeof x === "object" && x !== null && "timeSec" in x).map((x) => ({ timeSec: Number((x as any).timeSec) || 0, label: String((x as any).label ?? ""), description: String((x as any).description ?? "") })); } catch { return []; }
}
function parseAdjustmentLog(raw: string): z.infer<typeof adjustmentEntry>[] {
  try { const v = JSON.parse(raw) as unknown; if (!Array.isArray(v)) return []; return v.filter((x) => typeof x === "object" && x !== null).map((x: any) => ({ time: String(x.time ?? ""), reason: String(x.reason ?? ""), changes: String(x.changes ?? "") })); } catch { return []; }
}

function modeStatusOf(progress: number, override: string, hasCard: boolean): { status: string; label: string } {
  if (override === "conflict") return { status: "conflict", label: "风格冲突" };
  if (!hasCard && progress <= 0) return { status: "untrained", label: "未训练" };
  if (progress <= 3) return { status: "insufficient", label: "训练不足" };
  if (progress <= 6) return { status: "usable", label: "基础可用" };
  if (progress <= 8) return { status: "stable", label: "较稳定" };
  return { status: "mature", label: "成熟" };
}

function stabilityRank(s: string): number {
  return s === "高" ? 3 : s === "中" ? 2 : s === "低" ? 1 : 0;
}
function stabilityFromRank(r: number): string {
  return r >= 3 ? "高" : r === 2 ? "中" : "低";
}

async function ensureModes(ctx: Ctx) {
  const db = ctx.db<typeof schema>();
  const existing = await db.select().from(schema.modes);
  for (const seed of MODE_SEEDS) {
    if (!existing.some((m) => m.id === seed.id)) {
      await db.insert(schema.modes).values({
        id: seed.id,
        name: seed.name,
        iconSlot: seed.iconSlot,
        styleTags: "[]",
        progress: 0,
        stability: "",
        statusOverride: "",
      });
    }
  }
}

function cardToOut(c: typeof schema.styleCards.$inferSelect): z.infer<typeof styleCardOut> {
  return {
    id: c.id,
    modeId: c.modeId,
    themeStyle: c.themeStyle,
    rhythmStyle: c.rhythmStyle,
    dialogueStyle: c.dialogueStyle,
    pixelStyle: c.pixelStyle,
    hookStyle: (c as any).hookStyle ?? "",
    emotionCurve: (c as any).emotionCurve ?? "",
    narrativeStructure: (c as any).narrativeStructure ?? "",
    interactionDesign: (c as any).interactionDesign ?? "",
    viralSummary: (c as any).viralSummary ?? "",
    weights: parseWeights((c as any).weightsJson ?? "{}"),
    adjustmentLog: parseAdjustmentLog((c as any).adjustmentLog ?? "[]"),
    frames: parseFrames((c as any).framesJson ?? "[]"),
    transcriptText: (c as any).transcriptText ?? "",
    rhythmPoints: (c as any).rhythmPoints ?? "",
    addedTags: parseTagsJson(c.addedTags),
    correctedTags: parseTagsJson(c.correctedTags),
    stability: c.stability,
    sourceVideo: c.sourceVideo,
    confirmed: c.confirmed,
    version: c.version,
    createdAt: c.createdAt.toISOString(),
    updatedAt: c.updatedAt.toISOString(),
  };
}

function cardSnapshot(c: typeof schema.styleCards.$inferSelect | null): string {
  if (!c) return "";
  return JSON.stringify(cardToOut(c));
}

async function loadModeFull(ctx: Ctx, modeId: number): Promise<ModeFull | null> {
  const db = ctx.db<typeof schema>();
  const rows = await db.select().from(schema.modes).where(eq(schema.modes.id, modeId)).limit(1);
  const m = rows[0];
  if (!m) return null;
  const cards = await db
    .select()
    .from(schema.styleCards)
    .where(eq(schema.styleCards.modeId, modeId))
    .orderBy(desc(schema.styleCards.version));
  const current = m.currentStyleCardId != null
    ? cards.find((c) => c.id === m.currentStyleCardId) ?? null
    : null;
  const recs = await db
    .select()
    .from(schema.trainingRecords)
    .where(eq(schema.trainingRecords.modeId, modeId))
    .orderBy(desc(schema.trainingRecords.id));
  const st = modeStatusOf(m.progress, m.statusOverride, current != null);
  const curOut = current ? cardToOut(current) : null;
  const summary = curOut
    ? (curOut.viralSummary ? curOut.viralSummary : `主题：${curOut.themeStyle}；节奏：${curOut.rhythmStyle}；对话：${curOut.dialogueStyle}；像素：${curOut.pixelStyle}${curOut.hookStyle ? `；钩子：${curOut.hookStyle}` : ""}`)
    : "尚未投喂视频，暂无基因卡。";
  return {
    id: m.id,
    name: m.name,
    iconSlot: m.iconSlot,
    styleTags: parseTagsJson(m.styleTags),
    progress: m.progress,
    stability: m.stability,
    status: st.status,
    statusLabel: st.label,
    summary,
    coreLogic: coreLogicOf(m.id, (m as { coreLogic?: string }).coreLogic ?? ""),
    lastTrainedAt: m.lastTrainedAt ? m.lastTrainedAt.toISOString() : null,
    currentCard: current ? cardToOut(current) : null,
    cardHistory: cards.map(cardToOut),
    records: recs.map((r) => ({
      id: r.id,
      modeId: r.modeId,
      kind: r.kind,
      videoName: r.videoName,
      videoType: r.videoType,
      videoSizeBytes: r.videoSizeBytes,
      videoDurationSec: r.videoDurationSec,
      status: r.status,
      error: r.error,
      analysisSummary: r.analysisSummary,
      conflict: r.conflict === 1,
      progressBefore: r.progressBefore,
      progressAfter: r.progressAfter,
      stabilityBefore: r.stabilityBefore,
      stabilityAfter: r.stabilityAfter,
      revocable: r.revocable === 1,
      revoked: r.revoked === 1,
      feedbackReasons: parseTagsJson((r as any).feedbackReasons ?? "[]"),
      weightChanges: (r as any).weightChanges ?? "",
      createdAt: r.createdAt.toISOString(),
    })),
  };
}

// v5.20：轻量摘要加载——只读 modes 表一行；状态判定与 loadModeFull
// 同口径（modeStatusOf 的 hasCard 只看当前卡是否存在，等价于
// currentStyleCardId 非空），不加载基因卡与训练记录。
async function loadModeSummary(
  ctx: Ctx,
  modeId: number,
): Promise<ModeSummary | null> {
  const db = ctx.db<typeof schema>();
  const rows = await db
    .select()
    .from(schema.modes)
    .where(eq(schema.modes.id, modeId))
    .limit(1);
  const m = rows[0];
  if (!m) return null;
  const st = modeStatusOf(m.progress, m.statusOverride, m.currentStyleCardId != null);
  return {
    id: m.id,
    name: m.name,
    iconSlot: m.iconSlot,
    styleTags: parseTagsJson(m.styleTags),
    progress: m.progress,
    stability: m.stability,
    status: st.status,
    statusLabel: st.label,
    lastTrainedAt: m.lastTrainedAt ? m.lastTrainedAt.toISOString() : null,
  };
}

/** 当前项目选中模式的爆款基因上下文（供人物/大纲/剧本/分镜全链路注入）。 */
async function loadModeImitation(
  ctx: Ctx,
  projectId: number,
): Promise<{ modeName: string; part: string; geneSummary: string } | null> {
  const db = ctx.db<typeof schema>();
  const rows = await db.select().from(schema.projects).where(eq(schema.projects.id, projectId)).limit(1);
  const p = rows[0];
  if (!p || !p.selectedModeId) return null;
  const full = await loadModeFull(ctx, p.selectedModeId);
  if (!full || !full.currentCard) return null;
  const c = full.currentCard;
  const w = c.weights;
  const part = [
    `【爆款基因卡注入 · 依据${full.name}爆款基因卡生成】权重：主题${w.theme} 节奏${w.rhythm} 对话${w.dialogue} 像素${w.pixel} 钩子${w.hook} 情绪${w.emotion} 叙事${w.narrative} 互动${w.interaction}（0-200，越高越要强化该维度）`,
    c.viralSummary ? `爆款逻辑提炼摘要：${c.viralSummary}` : "",
    `主题：${c.themeStyle}`,
    `节奏：${c.rhythmStyle}${c.rhythmPoints ? `；节奏点：${c.rhythmPoints}` : ""}`,
    `对话：${c.dialogueStyle}`,
    `像素视觉：${c.pixelStyle}`,
    c.hookStyle ? `爆款钩子（前3秒）：${c.hookStyle} —— 人物开场、大纲第一段、剧本第一拍、分镜第一镜都必须呼应这个钩子` : "",
    c.emotionCurve ? `情绪曲线：${c.emotionCurve} —— 剧本台词与节拍必须按爽点/痛点/反转点的位置设计张力，审查时可对照` : "",
    c.narrativeStructure ? `叙事结构模板：${c.narrativeStructure} —— 大纲必须套用此框架，分段标题或正文要能看出结构名` : "",
    c.interactionDesign ? `互动/转化设计：${c.interactionDesign}` : "",
    c.addedTags.length > 0 ? `基因标签：${c.addedTags.join("、")}` : "",
    `生成要求：人物人设/语气/故事角色符合上述爆款调性；大纲套用叙事结构模板；剧本台词按情绪曲线制造张力；分镜运镜/切镜/时长分配匹配视觉节奏与高潮位置（节奏点）。`,
  ].filter(Boolean).join("\n");
  const geneSummary = `${c.hookStyle ? `钩子：${c.hookStyle} ` : ""}${c.narrativeStructure ? `结构：${c.narrativeStructure} ` : ""}${c.emotionCurve ? `情绪：${c.emotionCurve}` : ""}`.trim() || full.summary;
  return { modeName: full.name, part, geneSummary };
}

/** 某模式的全部优化建议行（新在前），列表展示与生成注入共用。 */
