/**
 * 本模式优化建议注入段（v4.21）：项目选中模式下用户在分镜页留下的
 * 全部建议，拼成一段「优化要求」文本，供剧本生成 / 生成故事流程 /
 * AI填写大纲三条生成链注入。没选模式或该模式还没有建议时返回 null
 * （不注入、不假装有建议）。
 */
async function loadModeSuggestionsPart(
  ctx: Ctx,
  projectId: number,
): Promise<string | null> {
  const db = ctx.db<typeof schema>();
  const rows = await db
    .select()
    .from(schema.projects)
    .where(eq(schema.projects.id, projectId))
    .limit(1);
  const p = rows[0];
  if (!p || !p.selectedModeId) return null;
  const sugg = await loadModeSuggestionRows(ctx, p.selectedModeId);
  const lines = sugg.map((s) => s.content.trim()).filter(Boolean);
  if (lines.length === 0) return null;
  const modeRows = await db
    .select()
    .from(schema.modes)
    .where(eq(schema.modes.id, p.selectedModeId))
    .limit(1);
  const modeName = modeRows[0]?.name ?? `模式${p.selectedModeId}`;
  return [
    `【${modeName}用户优化建议（用户看完按这个模式生成并拍成的视频后留下的改进意见，本次生成必须逐条落实；与爆款基因卡口径冲突时，以这些建议为准）】`,
    ...lines.map((l, i) => `${i + 1}. ${l}`),
  ].join("\n");
}

