/** 把基因卡提炼成「模式铁律」文本（审核与重写共用同一份口径）。 */
function viralIronRulesText(
modeId: number,
modeName: string,
card: z.infer<typeof styleCardOut> | null,
): string {
if (!card)
return "本项目所选模式没有基因卡（未训练）：只审通用三项（合规 / 爆款三要素 / 质量），不审模式铁律。";
if (modeId === 1)
return [
`【${modeName}铁律（依据基因卡，逐项硬查）】`,
"1. 双层结构完整性：全片必须明确分出「现在层 / 以前层」两层，每组先现在层铺垫、再以前层反转；大纲与剧本分不出层 = 不通过。",
"2. 跨层对话拦截：两层是不同时空——人物跨层对话、跨层点评、同一位妈妈串场两层，只要出现一处 = 直接不通过。",
"3. 快节奏：1–3 秒一镜、台词约 2 秒一句、梗句一出立刻硬切、无过渡拖沓；节奏拖沓的段落要指出。",
"4. 以前小孩主导：每组的反转与梗句收尾必须落在以前层，以前小孩把成人逻辑用童言认真执行到底；反转落在现在层 = 不通过。",
`基因卡依据——叙事结构：${card.narrativeStructure}`,
`对话：${card.dialogueStyle}`,
`钩子：${card.hookStyle}`,
`情绪曲线：${card.emotionCurve}`,
].join("\n");
if (modeId === 2)
return [
`【${modeName}铁律（依据基因卡，逐项硬查）】`,
"1. 每段先立一条荒诞规则（一句话能说清的离谱前提），没有规则的段 = 不通过。",
"2. 全员一本正经执行规则：人物越认真、表情越严肃越好；有人出戏吐槽、自己先笑场式拆台 = 不通过。",
"3. 每段以一句梗句（反转回答）收尾，收尾后立刻硬切下一段，不留过渡、不总结。",
"4. 荒诞度逐段递增：后一段的规则要比前一段更离谱，平行打转、后段不如前段 = 不通过。",
"5. 结尾必须是最强反转：最后一段的梗要压过前面所有段，平淡收尾 = 不通过。",
`基因卡依据——叙事结构：${card.narrativeStructure}`,
`对话：${card.dialogueStyle}`,
`钩子：${card.hookStyle}`,
`情绪曲线：${card.emotionCurve}`,
].join("\n");
return [
`【${modeName}基因卡（已训练）】按基因卡的叙事结构、对话风格、钩子与情绪曲线审：生成内容偏离基因卡模板的地方按模式铁律（mode_rule）指出。`,
`叙事结构：${card.narrativeStructure}`,
`对话：${card.dialogueStyle}`,
`钩子：${card.hookStyle}`,
].join("\n");
}


