type ModeHints = {
  genre?: string;
  mood?: string;
  rhythm?: string;
  dialogue?: string;
  pixel?: string;
  note?: string;
};

function fallbackDraft(hints: ModeHints & { transcript?: string }, videoName: string, prev: z.infer<typeof styleCardOut> | null, frames?: { timeSec: number; label: string }[], rhythmHint?: string): z.infer<typeof modeDraft> {
  const g = hints.genre?.trim() || "日常冲突题材";
  const mood = hints.mood?.trim() || "先压抑后释放";
  const hasTranscript = !!(hints.transcript && hints.transcript.trim().length > 4);
  const hook = `前3秒：以${g}的强冲突画面开场${hasTranscript ? `，首句台词「${hints.transcript!.trim().slice(0, 24)}…」直接抛矛盾` : "，人物表情与动作直接抛矛盾"}，不铺垫背景`;
  return {
    themeStyle: `${g}；情绪基调：${mood}；叙事母题：小人物在冲突中完成一次反击或和解`,
    rhythmStyle: hints.rhythm?.trim() || "快节奏：平均镜头2-4秒，前段密集切镜制造压迫，中段稍缓蓄力，高潮处切镜加速",
    dialogueStyle: hasTranscript ? `短句为主、语速偏快；台词密度高，围绕冲突反复拉扯，关键句重复强化记忆点（据用户提供/识别台词提炼）` : (hints.dialogue?.trim() || "短句为主、冲突式对话，问答节奏快，情绪词密度高"),
    pixelStyle: hints.pixel?.trim() || "高对比画面、近景人物占比大、背景简洁突出主体，抽帧显示前3秒即出现人物特写",
    hookStyle: hook,
    emotionCurve: "痛点约0-3秒（被轻视/陷入困境）→ 爽点约中段55%处（第一次反击成功）→ 反转点约80%处（身份或真相揭晓）→ 爽点收尾在最后3秒",
    narrativeStructure: "框架：钩子-冲突升级-反转-爽点收尾；分段：1钩子段(前3秒抛冲突) 2升级段(矛盾加码) 3反转段(关键信息揭晓) 4收尾段(爽点落地+留互动钩子)",
    interactionDesign: "无",
    viralSummary: `这个视频靠「3秒强冲突钩子 + 中段反击爽点 + 结尾反转」爆：①前3秒不铺垫直接抛矛盾，完播门槛低；②情绪曲线先压后扬，痛点与爽点距离近；③短句高密度台词便于记忆与模仿；④叙事结构是可复用的四段框架；⑤结尾留反转余味促评论。来源视频「${videoName}」`,
    rhythmPoints: rhythmHint || "高潮候选点约在总时长70-85%处；高潮前切镜变密、单镜变短，高潮后用一个长一点的反应镜头收住情绪",
    frameDescriptions: (frames ?? []).map((f) => ({ timeSec: f.timeSec, label: f.label, description: "抽帧已保存，画面描述以本次多模态分析为准（回退草稿未逐帧细描）" })),
    addedTags: [g, mood, "3秒强冲突钩子", "先压后扬"].filter(Boolean).slice(0, 6),
    correctedTags: [],
    summary: `已为「${videoName}」生成爆款基因卡（含八维与爆款逻辑提炼摘要）${prev ? "，已对照上一版基因卡增补" : ""}。`,
    stability: prev ? "中" : "低",
  };
}

/** 主题信号重合度：两个主题文本的二字片段交集 / 较小集合大小。 */
function themeOverlapRatio(a: string, b: string): number {
  const grams = (s: string) => {
    const set = new Set<string>();
    const clean = s.replace(/[\s，。；、：:·「」『』（）()]/g, "");
    for (let i = 0; i + 2 <= clean.length; i++) set.add(clean.slice(i, i + 2));
    return set;
  };
  const ga = grams(a);
  const gb = grams(b);
  if (ga.size === 0 || gb.size === 0) return 1;
  let shared = 0;
  for (const g of gb) if (ga.has(g)) shared++;
  return shared / Math.min(ga.size, gb.size);
}

const VIDEO_EXTS = ["mp4", "mov", "webm"];
const VIDEO_MAX_BYTES = 200 * 1024 * 1024;
const VIDEO_MAX_SEC = 600;
const VIDEO_MIN_SEC = 2;

function validateVideoInfo(v: { videoName: string; videoType: string; videoSizeBytes: number; videoDurationSec: number }): string | null {
  const ext = (v.videoName.split(".").pop() ?? "").toLowerCase();
  if (!VIDEO_EXTS.includes(ext) && !v.videoType.startsWith("video/")) {
    return `格式不支持：只接受 MP4 / MOV / WebM 视频（这个文件是 .${ext || "未知"}）。`;
  }
  if (v.videoSizeBytes <= 0) return "没读到视频文件大小，请重新选择视频文件。";
  if (v.videoSizeBytes > VIDEO_MAX_BYTES) return `视频太大：上限 200MB，这个文件约 ${Math.round(v.videoSizeBytes / 1024 / 1024)}MB。`;
  if (v.videoDurationSec > 0 && v.videoDurationSec < VIDEO_MIN_SEC) return `视频太短：至少 ${VIDEO_MIN_SEC} 秒。`;
  if (v.videoDurationSec > VIDEO_MAX_SEC) return `视频太长：上限 10 分钟，这个视频约 ${Math.round(v.videoDurationSec)} 秒。`;
  return null;
}

// ---------------------------------------------------------------------------
// v3.64 剧本人物逐人同步到储存库（与上面整项目批量导入并存，批量
// 导入不动）：一个人物一次同步，先出计划（将新建还是更新、目标卡
// 名、图带不带得过去）给用户确认，确认后才写入。去重顺序写死：
//   ① 人物已有 sourcePresetId 且该预设还在 → 更新那张卡；
//   ② 否则按姓名在储存库里查重，命中 → 更新命中卡；同名有多张时
//      优先备注完全一致的那张、否则最早的一张，计划里明示命中
//      哪张、同名共几张，用户看完确认才写入；
//   ③ 都没有 → 新建一张卡。
// 同步内容：人物名、备注（原样写进卡面备注，身份从备注的「身份：…」
// 段读回卡面扮演，与批量导入同一口径）。图片口径 v3.66 改为复制
// 数据本身（见 syncCharacterToLibrary 注释），不再贴共享引用。
// 写入后把对应关系回写到人物卡（sourcePresetId / sourcePresetName），
// 第二次同步必是更新、绝不重复建卡。目标卡已锁定时不覆盖，明确
// 报错让用户先解锁。
// ---------------------------------------------------------------------------

type LibrarySyncTarget =
  | {
      action: "update";
      via: "source" | "name";
      preset: AssetPresetRow;
      /** 按姓名命中时同名卡的总数（>1 时计划里明示命中了哪张）。 */
      sameNameCount: number;
    }
  | { action: "create"; via: null; preset: null; sameNameCount: 0 };

async function resolveLibrarySyncTarget(
  ctx: Ctx,
  c: typeof schema.characters.$inferSelect,
): Promise<LibrarySyncTarget> {
  const db = ctx.db<typeof schema>();
  if (c.sourcePresetId != null) {
    const rows = await db
      .select()
      .from(schema.assetPresets)
      .where(eq(schema.assetPresets.id, c.sourcePresetId));
    if (rows[0])
      return { action: "update", via: "source", preset: rows[0], sameNameCount: 0 };
  }
  const name = c.name.trim();
  if (name) {
    const presets = await db
      .select()
      .from(schema.assetPresets)
      .orderBy(asc(schema.assetPresets.id));
    const sameName = presets.filter((p) => p.name.trim() === name);
    if (sameName.length > 0) {
      // 同名多张：优先备注与这位人物完全一致的，其次最早建的一张。
      const hit =
        sameName.find((p) => p.cardNote === c.note) ?? sameName[0];
      if (hit)
        return {
          action: "update",
          via: "name",
          preset: hit,
          sameNameCount: sameName.length,
        };
    }
  }
  return { action: "create", via: null, preset: null, sameNameCount: 0 };
}

