type BackupManifest = z.infer<typeof backupManifest>;

async function backupRefForKey(
  ctx: Ctx,
  key: string | null,
  mimeFallback: string,
): Promise<z.infer<typeof backupImageRef> | null> {
  if (!key) return null;
  const head = await ctx.blobs.head(key);
  if (!head) {
    return {
      blobKey: key,
      url: "",
      mimeType: mimeFallback || "image/jpeg",
      sizeBytes: 0,
      etag: "",
      missing: true,
    };
  }
  return {
    blobKey: key,
    url: await ctx.blobs.getUrl(key),
    mimeType: head.contentType || mimeFallback || "image/jpeg",
    sizeBytes: head.sizeBytes ?? head.size ?? 0,
    etag: head.etag ?? "",
    missing: false,
  };
}

/** 性格的独立落点：v3.69 手动「填写」把性格以「性格：…」标签段存进
 * cardNote。导出时用与客户端 parseBasicInfo 相同的口径从备注里摘出
 * 性格段单独成字段；没有性格段就是空字符串，绝不从别处猜。 */
function personalityFromNote(note: string): string {
  const m = note.match(/性格[:：]\s*([^；;\n]+)/);
  return m?.[1] ? m[1].trim().replace(/。+$/, "").trim() : "";
}

/** 导入写回性格：personality 非空时，确保 cardNote 里有值一致的
 * 「性格：」段——已有段就校正为该值，没有就追加到备注末尾。 */
function noteWithPersonality(note: string, personality: string): string {
  const p = personality.trim();
  if (!p) return note;
  if (/性格[:：]/.test(note)) {
    return note.replace(/性格[:：]\s*[^；;\n]+/, `性格：${p}`);
  }
  return note.trim() ? `${note.trim()}；性格：${p}` : `性格：${p}`;
}

