// v4.15 场景资产规范句：场景图是无人空镜的场景设定图——与人物图同
// 一套超写实CG画风，但排版完全不同（单幅 16:9 广角全景、无人、无
// 文字）。AI 只写「场景本体」段，这两句由服务端统一拼在后面；生图
// 面板对场景不开三视图，拼好即最终词，不会再叠三视图句。
const SCENE_PROMPT_ART_ZH = "超写实CG风格，真实材质肌理与真实光影，电影级CG渲染，环境细节拉满，8K超高清";
const SCENE_PROMPT_ART_EN = "ultra-realistic CG style, true material textures and realistic lighting, cinematic CG rendering, highly detailed environment, 8K ultra-detailed";
const SCENE_PROMPT_LAYOUT_ZH = "场景设定图：16:9 一张图，广角全景空镜，画面里没有任何人物，完整呈现整个场景的空间布局、陈设与氛围；无文字，无水印";
const SCENE_PROMPT_LAYOUT_EN = "environment concept art: one 16:9 wide establishing shot, empty scene with absolutely no people or characters, full spatial layout, furnishings and atmosphere visible; no text, no watermark";

function composeScenePrompt(bodyZh: string, bodyEn: string): { promptZh: string; promptEn: string } {
const zhBody = bodyZh.trim().replace(/[；;。]+$/, "");
const enBody = bodyEn.trim().replace(/[;.]+$/, "");
return {
promptZh: [zhBody, SCENE_PROMPT_ART_ZH, SCENE_PROMPT_LAYOUT_ZH].filter(Boolean).join("；"),
promptEn: [enBody, SCENE_PROMPT_ART_EN, SCENE_PROMPT_LAYOUT_EN].filter(Boolean).join("; "),
};
}

function composeCharacterPrompt(lookZh: string, lookEn: string): { promptZh: string; promptEn: string } {
const zhBody = lookZh.trim().replace(/[；;。]+$/, "");
const enBody = lookEn.trim().replace(/[;.]+$/, "");
return {
promptZh: [zhBody, CHAR_PROMPT_ART_ZH, CHAR_PROMPT_THREE_VIEW_ZH].filter(Boolean).join("；"),
promptEn: [enBody, CHAR_PROMPT_ART_EN, CHAR_PROMPT_THREE_VIEW_ZH].filter(Boolean).join("; "),
};
}
