// v4.37 监控时间解析（发布时间 / 采集时间共用）：快手的时间是北京
// 时间，无时区后缀的「YYYY-MM-DD HH:mm」一律按 Asia/Shanghai 解释
// （UTC+8），不随服务端时区漂移；带 Z / ±hh:mm 后缀的 ISO 串按其
// 自身时区解析。空串回 { date: null }，看不懂回 { invalid: true }。
function parseMonitorDateTime(raw: string): { date: Date | null; invalid?: boolean } {
  const s = raw.trim();
  if (!s) return { date: null };
  const naive = s.match(
    /^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/,
  );
  if (naive) {
    return {
      date: new Date(
        Date.UTC(
          Number(naive[1]),
          Number(naive[2]) - 1,
          Number(naive[3]),
          Number(naive[4]) - 8,
          Number(naive[5]),
          Number(naive[6] ?? 0),
        ),
      ),
    };
  }
  const d = new Date(s.replace(" ", "T"));
  if (Number.isNaN(d.getTime())) return { date: null, invalid: true };
  return { date: d };
}

