const transcriptSegmentOut = z.object({
  start: z.number(),
  end: z.number(),
  text: z.string(),
  speakerCluster: z.string(),
  confidence: z.number(),
  lowConfidence: z.boolean(),
});

// v4.86 转写改后台任务制后的启动 / 轮询出参（审计修正：同步转写
// 撞单次请求时限，启动只回 jobId、轮询 done 才带 segments）。
const transcribeStartResponse = z.object({
  ok: z.boolean(),
  error: z.string().nullable(),
  jobId: z.string().nullable(),
  source: z.enum(["cloud", "upload"]),
});

type TranscribeStartResult = z.infer<typeof transcribeStartResponse>;

const transcribePollResponse = z.object({
  status: z.enum(["running", "done", "failed"]),
  ok: z.boolean(),
  error: z.string().nullable(),
  source: z.enum(["cloud", "upload"]),
  durationSec: z.number(),
  segments: z.array(transcriptSegmentOut),
});

type TranscribePollResult = z.infer<typeof transcribePollResponse>;

function parseTranscriptSegments(segmentsJson: string): z.infer<typeof transcriptSegmentOut>[] {
  try {
    const raw = JSON.parse(segmentsJson) as unknown[];
    if (!Array.isArray(raw)) return [];
    const out: z.infer<typeof transcriptSegmentOut>[] = [];
    for (const r of raw) {
      if (!r || typeof r !== "object") continue;
      const o = r as Record<string, unknown>;
      const start = typeof o.start === "number" ? o.start : NaN;
      const end = typeof o.end === "number" ? o.end : NaN;
      const text = typeof o.text === "string" ? o.text.trim() : "";
      if (!Number.isFinite(start) || !Number.isFinite(end) || !text) continue;
      out.push({
        start: Math.round(start * 10) / 10,
        end: Math.round(Math.max(end, start) * 10) / 10,
        text,
        speakerCluster: typeof o.cluster === "string" && o.cluster ? o.cluster : "S1",
        confidence: typeof o.confidence === "number" ? o.confidence : 0,
        lowConfidence: o.lowConfidence === true,
      });
    }
    return out.sort((a, b) => a.start - b.start);
  } catch {
    return [];
  }
}


